import React, { useState, useEffect, useRef } from 'react';
import './App.css';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import { useAuth } from './hooks/useAuth';

// Prefilled from .env.local (REACT_APP_* are inlined at build time)
const DEFAULT_USERNAME = process.env.REACT_APP_ADMIN_USERNAME ?? '';
const DEFAULT_PASSWORD = process.env.REACT_APP_ADMIN_PASSWORD ?? '';

function App() {
  const { user, login, logout, isAuthenticated } = useAuth();
  const [loginError, setLoginError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const usernameRef = useRef<HTMLInputElement>(null);

  // Auto-focus username on mount (unless already filled)
  useEffect(() => {
    if (!isAuthenticated && usernameRef.current && !DEFAULT_USERNAME) {
      usernameRef.current.focus();
    }
  }, [isAuthenticated]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError('');
    setIsLoading(true);

    const formData = new FormData(e.currentTarget as HTMLFormElement);
    const credentials = {
      username: (formData.get('username') as string).trim(),
      password: formData.get('password') as string,
    };

    if (!credentials.username || !credentials.password) {
      setLoginError('Please enter both username and password.');
      setIsLoading(false);
      return;
    }

    const success = await login(credentials);
    setIsLoading(false);

    if (!success) {
      setLoginError('Incorrect username or password. Please try again.');
    }
  };

  const handleLogout = () => logout();

  if (!isAuthenticated) {
    return (
      <div className="login-page">
        <div className="login-container" role="main">
          {/* Brand */}
          <header className="login-brand">
            <div className="login-logo" aria-hidden="true">🚗</div>
            <h1>Mr. Rideo</h1>
            <p>Admin Portal</p>
          </header>

          {/* Error */}
          {loginError && (
            <div
              id="login-error"
              className="login-error"
              role="alert"
              aria-live="assertive"
            >
              <span className="login-error-icon" aria-hidden="true">⚠</span>
              {loginError}
            </div>
          )}

          {/* Form */}
          <form
            className="login-form"
            onSubmit={handleLogin}
            noValidate
            aria-label="Admin sign-in form"
            aria-describedby={loginError ? 'login-error' : undefined}
          >
            <div className="form-group">
              <label className="form-label" htmlFor="username">
                Username
              </label>
              <input
                id="username"
                ref={usernameRef}
                className="form-input"
                type="text"
                name="username"
                defaultValue={DEFAULT_USERNAME}
                autoComplete="username"
                spellCheck={false}
                autoCapitalize="none"
                required
                disabled={isLoading}
                aria-required="true"
              />
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="password">
                Password
              </label>
              <div className="input-wrapper">
                <input
                  id="password"
                  className="form-input with-action"
                  type={showPassword ? 'text' : 'password'}
                  name="password"
                  defaultValue={DEFAULT_PASSWORD}
                  autoComplete="current-password"
                  required
                  disabled={isLoading}
                  aria-required="true"
                />
                <button
                  type="button"
                  className="input-action-btn"
                  onClick={() => setShowPassword(v => !v)}
                  aria-label={showPassword ? 'Hide password' : 'Show password'}
                  tabIndex={-1}
                  disabled={isLoading}
                >
                  {showPassword ? '🙈' : '👁'}
                </button>
              </div>
            </div>

            <button
              id="login-submit-btn"
              className="btn-primary"
              type="submit"
              disabled={isLoading}
              aria-busy={isLoading}
            >
              {isLoading
                ? <><span className="login-spinner" aria-hidden="true" /> Signing in…</>
                : 'Sign in'}
            </button>
          </form>

          <p className="login-footer-note">
            Authorised personnel only. All activity is logged.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="App">
      <Sidebar user={user} onLogout={handleLogout} />
      <main className="main-content" id="main-content" tabIndex={-1}>
        <Dashboard />
      </main>
    </div>
  );
}

export default App;
